#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
#include <openssl/evp.h>
#include <pthread.h>

// OpenSSL internal-ish but exported
void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp,
                    size_t len, const unsigned int key[8],
                    const unsigned int counter[4]);

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

#define N (40*1024*1024)

static unsigned char key[32];
static unsigned char nonce[12];
static unsigned char *pt;
static unsigned char *out;

static void enc_chacha(unsigned char *dst, const unsigned char *src, size_t len, uint32_t counter_start) {
    unsigned int k[8];
    unsigned int ctr[4];
    memcpy(k, key, 32);
    ctr[0] = counter_start;
    memcpy(ctr+1, nonce, 12);
    ChaCha20_ctr32(dst, src, len, k, ctr);
}

typedef struct {
    size_t off;
    size_t len;
    uint32_t counter;
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    enc_chacha(out + j->off, pt + j->off, j->len, j->counter);
    return NULL;
}

int main() {
    FILE *f = fopen("/dev/urandom", "rb");
    fread(key, 1, 32, f);
    fread(nonce, 1, 12, f);
    pt = malloc(N);
    out = malloc(N);
    unsigned char *out2 = malloc(N+16);
    fread(pt, 1, N, f);
    fclose(f);

    // warmup
    enc_chacha(out, pt, N, 1);
    double t0 = now();
    int reps = 5;
    for (int i = 0; i < reps; i++) enc_chacha(out, pt, N, 1);
    double t1 = now();
    printf("ChaCha20_ctr32 single thread: %.2f ms  %.0f MB/s\n", (t1-t0)/reps*1000, N/((t1-t0)/reps)/1e6);

    // parallel 4 threads, split by 64-byte blocks
    int nthreads = 4;
    pthread_t th[8];
    job_t jobs[8];
    size_t block = 64;
    size_t total_blocks = N / block;
    size_t blocks_per = total_blocks / nthreads;
    t0 = now();
    for (int r = 0; r < reps; r++) {
        for (int i = 0; i < nthreads; i++) {
            jobs[i].off = i * blocks_per * block;
            jobs[i].len = (i == nthreads-1) ? (N - jobs[i].off) : blocks_per * block;
            jobs[i].counter = 1 + (uint32_t)(jobs[i].off / block);
            pthread_create(&th[i], NULL, worker, &jobs[i]);
        }
        for (int i = 0; i < nthreads; i++) pthread_join(th[i], NULL);
    }
    t1 = now();
    printf("ChaCha20_ctr32 %d threads: %.2f ms  %.0f MB/s\n", nthreads, (t1-t0)/reps*1000, N/((t1-t0)/reps)/1e6);

    nthreads = 6;
    blocks_per = total_blocks / nthreads;
    t0 = now();
    for (int r = 0; r < reps; r++) {
        for (int i = 0; i < nthreads; i++) {
            jobs[i].off = i * blocks_per * block;
            jobs[i].len = (i == nthreads-1) ? (N - jobs[i].off) : blocks_per * block;
            jobs[i].counter = 1 + (uint32_t)(jobs[i].off / block);
            pthread_create(&th[i], NULL, worker, &jobs[i]);
        }
        for (int i = 0; i < nthreads; i++) pthread_join(th[i], NULL);
    }
    t1 = now();
    printf("ChaCha20_ctr32 %d threads: %.2f ms  %.0f MB/s\n", nthreads, (t1-t0)/reps*1000, N/((t1-t0)/reps)/1e6);

    // EVP baseline
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char aad[32] = {0};
    int outlen, tmplen;
    unsigned char tag[16];
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ctx, out2, &outlen, pt, N);
        EVP_EncryptFinal_ex(ctx, out2+outlen, &tmplen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    t0 = now();
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ctx, out2, &outlen, pt, N);
        EVP_EncryptFinal_ex(ctx, out2+outlen, &tmplen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    t1 = now();
    printf("EVP chacha20-poly1305: %.2f ms  %.0f MB/s\n", (t1-t0)/reps*1000, N/((t1-t0)/reps)/1e6);

    // verify chacha matches first N of EVP? EVP includes poly1305 so ciphertext portion should match ChaCha20 with counter=1
    enc_chacha(out, pt, N, 1);
    if (memcmp(out, out2, N) == 0) printf("MATCH ciphertext\n");
    else {
        printf("MISMATCH\n");
        for (int i = 0; i < 32; i++) printf("%02x ", out[i]);
        printf("\n");
        for (int i = 0; i < 32; i++) printf("%02x ", out2[i]);
        printf("\n");
    }
    return 0;
}
