{"command":"cd "$HOME/chacha_bench" && cat > ext.c << 'EOF'
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp,
                    size_t len, const unsigned int key[8],
                    const unsigned int counter[4]);

typedef struct {
    unsigned char *out;
    const unsigned char *in;
    size_t len;
    unsigned int key[8];
    unsigned int counter[4];
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    ChaCha20_ctr32(j->out, j->in, j->len, j->key, j->counter);
    return NULL;
}

/* persistent thread pool */
#define MAX_THREADS 8
static int pool_n = 0;
static pthread_t threads[MAX_THREADS];
static job_t jobs[MAX_THREADS];
static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv_start = PTHREAD_COND_INITIALIZER;
static pthread_cond_t cv_done = PTHREAD_COND_INITIALIZER;
static int start_epoch = 0;
static int done_count = 0;
static int shutdown_flag = 0;
static int pool_ready = 0;

static void *pool_worker(void *arg) {
    int id = (int)(intptr_t)arg;
    int seen = 0;
    pthread_mutex_lock(&mu);
    while (1) {
        while (seen == start_epoch && !shutdown_flag) {
            pthread_cond_wait(&cv_start, &mu);
        }
        if (shutdown_flag) { pthread_mutex_unlock(&mu); return NULL; }
        seen = start_epoch;
        pthread_mutex_unlock(&mu);

        ChaCha20_ctr32(jobs[id].out, jobs[id].in, jobs[id].len, jobs[id].key, jobs[id].counter);

        pthread_mutex_lock(&mu);
        done_count++;
        if (done_count == pool_n) pthread_cond_signal(&cv_done);
    }
}

static void ensure_pool(int n) {
    if (pool_ready) return;
    pool_n = n;
    for (int i = 0; i < n; i++) {
        pthread_create(&threads[i], NULL, pool_worker, (void*)(intptr_t)i);
    }
    pool_ready = 1;
}

static void run_pool(void) {
    pthread_mutex_lock(&mu);
    done_count = 0;
    start_epoch++;
    pthread_cond_broadcast(&cv_start);
    while (done_count < pool_n) pthread_cond_wait(&cv_done, &mu);
    pthread_mutex_unlock(&mu);
}

/* Poly1305 */
typedef struct poly1305_context {
    size_t aligner;
    unsigned char opaque[136]; /* Poly1305_ctx is small; be generous */
} poly1305_context;

/* We use OpenSSL Poly1305_* which take a raw ctx of Poly1305_ctx_size() */
size_t Poly1305_ctx_size(void);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

static PyObject *encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, plaintext, aad;
    int nthreads = 4;
    if (!PyArg_ParseTuple(args, "y*y*y*y*|i", &key, &nonce, &plaintext, &aad, &nthreads))
        return NULL;
    if (key.len != 32 || nonce.len != 12) {
        PyBuffer_Release(&key); PyBuffer_Release(&nonce);
        PyBuffer_Release(&plaintext); PyBuffer_Release(&aad);
        PyErr_SetString(PyExc_ValueError, "bad key/nonce size");
        return NULL;
    }
    if (nthreads < 1) nthreads = 1;
    if (nthreads > MAX_THREADS) nthreads = MAX_THREADS;

    Py_ssize_t N = plaintext.len;
    /* allocate ciphertext bytes uninitialized and tag bytes */
    PyObject *ct = PyBytes_FromStringAndSize(NULL, N);
    PyObject *tag = PyBytes_FromStringAndSize(NULL, 16);
    if (!ct || !tag) {
        Py_XDECREF(ct); Py_XDECREF(tag);
        PyBuffer_Release(&key); PyBuffer_Release(&nonce);
        PyBuffer_Release(&plaintext); PyBuffer_Release(&aad);
        return NULL;
    }
    unsigned char *ct_buf = (unsigned char *)PyBytes_AS_STRING(ct);
    unsigned char *tag_buf = (unsigned char *)PyBytes_AS_STRING(tag);
    const unsigned char *pt = (const unsigned char *)plaintext.buf;

    /* keystream block 0 for poly1305 key */
    unsigned char poly_key_block[64];
    unsigned int k[8];
    unsigned int ctr[4];
    memcpy(k, key.buf, 32);
    ctr[0] = 0;
    memcpy(ctr + 1, nonce.buf, 12);
    ChaCha20_ctr32(poly_key_block, NULL, 64, k, ctr); /* inp NULL means zero? check */

    /* Actually ChaCha20_ctr32 with inp==NULL may crash. Generate keystream by encrypting zeros. */
    memset(poly_key_block, 0, 64);
    ChaCha20_ctr32(poly_key_block, poly_key_block, 64, k, ctr);

    /* parallel encrypt body with counter starting at 1 */
    if (N > 0) {
        if (nthreads == 1 || N < 256*1024) {
            ctr[0] = 1;
            ChaCha20_ctr32(ct_buf, pt, (size_t)N, k, ctr);
        } else {
            ensure_pool(nthreads);
            size_t block = 64;
            size_t total_blocks = ((size_t)N) / block; /* full blocks; tail handled by last */
            /* split on 64-byte boundaries */
            size_t blocks_per = total_blocks / nthreads;
            if (blocks_per == 0) {
                ctr[0] = 1;
                ChaCha20_ctr32(ct_buf, pt, (size_t)N, k, ctr);
            } else {
                for (int i = 0; i < nthreads; i++) {
                    size_t off = (size_t)i * blocks_per * block;
                    size_t len = (i == nthreads - 1) ? ((size_t)N - off) : blocks_per * block;
                    jobs[i].out = ct_buf + off;
                    jobs[i].in = pt + off;
                    jobs[i].len = len;
                    memcpy(jobs[i].key, k, 32);
                    jobs[i].counter[0] = 1 + (unsigned int)(off / block);
                    memcpy(jobs[i].counter + 1, nonce.buf, 12);
                }
                run_pool();
            }
        }
    }

    /* Poly1305 over AEAD construction:
       pad16(aad) || pad16(ct) || le64(len(aad)) || le64(len(ct))
       keyed with first 32 bytes of block 0.
    */
    void *pctx = PyMem_Malloc(Poly1305_ctx_size());
    Poly1305_Init(pctx, poly_key_block);

    const unsigned char *aad_buf = (const unsigned char *)aad.buf;
    size_t aad_len = (size_t)aad.len;
    Poly1305_Update(pctx, aad_buf, aad_len);
    size_t aad_pad = (16 - (aad_len & 15)) & 15;
    if (aad_pad) {
        unsigned char zeros[16] = {0};
        Poly1305_Update(pctx, zeros, aad_pad);
    }
    Poly1305_Update(pctx, ct_buf, (size_t)N);
    size_t ct_pad = (16 - ((size_t)N & 15)) & 15;
    if (ct_pad) {
        unsigned char zeros[16] = {0};
        Poly1305_Update(pctx, zeros, ct_pad);
    }
    unsigned char lens[16];
    uint64_t al = (uint64_t)aad_len, cl = (uint64_t)N;
    memcpy(lens, &al, 8);
    memcpy(lens + 8, &cl, 8);
    Poly1305_Update(pctx, lens, 16);
    Poly1305_Final(pctx, tag_buf);
    PyMem_Free(pctx);

    /* wipe poly key */
    OPENSSL_cleanse(poly_key_block, 64);

    PyBuffer_Release(&key); PyBuffer_Release(&nonce);
    PyBuffer_Release(&plaintext); PyBuffer_Release(&aad);

    return Py_BuildValue("(NN)", ct, tag);
}

static PyMethodDef methods[] = {
    {"encrypt", encrypt, METH_VARARGS, "encrypt"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "chacha_fast", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_chacha_fast(void) {
    return PyModule_Create(&moduledef);
}
EOF
