    pthread_cond_broadcast(&cv_start);
    while (done_count < pool_n) pthread_cond_wait(&cv_done, &mu);
    pthread_mutex_unlock(&mu);
}

static PyObject *chacha_encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, plaintext, aad;
    int nthreads = 4;
    if (!PyArg_ParseTuple(args, "y*y*y*y*|i", &key, &nonce, &plaintext, &aad, &nthreads))
        return NULL;
    if (key.len != 32 || nonce.len != 12) {
        PyBuffer_Release(&key);
        PyBuffer_Release(&nonce);
        PyBuffer_Release(&plaintext);
        PyBuffer_Release(&aad);
        PyErr_SetString(PyExc_ValueError, "bad key/nonce size");
        return NULL;
    }
    if (nthreads < 1) nthreads = 1;
    if (nthreads > MAX_THREADS) nthreads = MAX_THREADS;

    Py_ssize_t N = plaintext.len;
    PyObject *ct = PyBytes_FromStringAndSize(NULL, N);
    PyObject *tag = PyBytes_FromStringAndSize(NULL, 16);
    if (!ct || !tag) {
        Py_XDECREF(ct);
        Py_XDECREF(tag);
        PyBuffer_Release(&key);
        PyBuffer_Release(&nonce);
        PyBuffer_Release(&plaintext);
        PyBuffer_Release(&aad);
        return NULL;
    }
    unsigned char *ct_buf = (unsigned char *)PyBytes_AS_STRING(ct);
    unsigned char *tag_buf = (unsigned char *)PyBytes_AS_STRING(tag);
    const unsigned char *pt = (const unsigned char *)plaintext.buf;

    /* key and counter must be 32-byte aligned for ChaCha20_ctr32 AVX2 path */
    unsigned int k[8] __attribute__((aligned(32)));
    unsigned int ctr[4] __attribute__((aligned(32)));
    memcpy(k, key.buf, 32);
    ctr[0] = 0;
    memcpy(ctr + 1, nonce.buf, 12);

    unsigned char poly_key_block[64] __attribute__((aligned(32)));
    memset(poly_key_block, 0, 64);
    ChaCha20_ctr32(poly_key_block, poly_key_block, 64, k, ctr);

    if (N > 0) {
        if (nthreads == 1 || N < 256 * 1024) {
            ctr[0] = 1;
            ChaCha20_ctr32(ct_buf, pt, (size_t)N, k, ctr);
        } else {
            ensure_pool(nthreads);
            size_t block = 64;
            size_t total_blocks = ((size_t)N) / block;
            size_t blocks_per = total_blocks / (size_t)nthreads;
            if (blocks_per == 0) {
                ctr[0] = 1;
                ChaCha20_ctr32(ct_buf, pt, (size_t)N, k, ctr);
            } else {
                for (int i = 0; i < nthreads; i++) {
                    size_t off = (size_t)i * blocks_per * block;
                    size_t len = (i == nthreads - 1) ? ((size_t)N - off) : blocks_per * block;
                    jobs[i].out = ct_buf + off;
                    jobs[i].in = pt + off;
                    jobs[i].len = len;
                    memcpy(jobs[i].key, k, 32);
                    jobs[i].counter[0] = 1 + (unsigned int)(off / block);
                    memcpy(jobs[i].counter + 1, nonce.buf, 12);
                }
                run_pool();
            }
        }
    }

    size_t ctx_sz = Poly1305_ctx_size();
    void *pctx = NULL;
    if (posix_memalign(&pctx, 64, ctx_sz + 64) != 0) {
        Py_DECREF(ct);
        Py_DECREF(tag);
        PyBuffer_Release(&key);
        PyBuffer_Release(&nonce);
        PyBuffer_Release(&plaintext);
        PyBuffer_Release(&aad);
        return PyErr_NoMemory();
    }
    memset(pctx, 0, ctx_sz + 64);
    Poly1305_Init(pctx, poly_key_block);

    const unsigned char *aad_buf = aad.buf ? (const unsigned char *)aad.buf : (const unsigned char *)"";
    size_t aad_len = (size_t)aad.len;
    if (aad_len) Poly1305_Update(pctx, aad_buf, aad_len);
    size_t aad_pad = (16 - (aad_len & 15)) & 15;
    unsigned char zeros[16] = {0};
    if (aad_pad) Poly1305_Update(pctx, zeros, aad_pad);
    if (N) Poly1305_Update(pctx, ct_buf, (size_t)N);
    size_t ct_pad = (16 - ((size_t)N & 15)) & 15;
    if (ct_pad) Poly1305_Update(pctx, zeros, ct_pad);
    unsigned char lens[16];
    uint64_t al = (uint64_t)aad_len, cl = (uint64_t)N;
    memcpy(lens, &al, 8);
    memcpy(lens + 8, &cl, 8);
    Poly1305_Update(pctx, lens, 16);
    Poly1305_Final(pctx, tag_buf);
    free(pctx);
    OPENSSL_cleanse(poly_key_block, 64);

    PyBuffer_Release(&key);
    PyBuffer_Release(&nonce);
    PyBuffer_Release(&plaintext);
    PyBuffer_Release(&aad);
    return Py_BuildValue("(NN)", ct, tag);
}

static PyMethodDef methods[] = {
    {"encrypt", chacha_encrypt, METH_VARARGS, "encrypt"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "chacha_fast", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_chacha_fast(void) {
    return PyModule_Create(&moduledef);
}
EOF
cc -O3 -shared -fPIC -o chacha_fast.so ext.c \
