{"command":"cd "$HOME/chacha_bench" && cat > poolbench.c << 'EOF'
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp,
                    size_t len, const unsigned int key[8],
                    const unsigned int counter[4]);
size_t Poly1305_ctx_size(void);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);
static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}
#define N (40u*1024u*1024u)
#define MAX_THREADS 8
typedef struct {
    unsigned char *out, *in;
    size_t len;
    unsigned int key[8];
    unsigned int counter[4];
    int id;
} job_t;
static job_t jobs[MAX_THREADS];
static pthread_t threads[MAX_THREADS];
static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv_start = PTHREAD_COND_INITIALIZER;
static pthread_cond_t cv_done = PTHREAD_COND_INITIALIZER;
static int start_epoch = 0, done_count = 0, pool_n = 0;
static void *worker(void *arg) {
    int id = (int)(intptr_t)arg;
    int seen = 0;
    pthread_mutex_lock(&mu);
    for (;;) {
        while (seen == start_epoch) pthread_cond_wait(&cv_start, &mu);
        seen = start_epoch;
        pthread_mutex_unlock(&mu);
        ChaCha20_ctr32(jobs[id].out, jobs[id].in, jobs[id].len, jobs[id].key, jobs[id].counter);
        pthread_mutex_lock(&mu);
        done_count++;
        if (done_count == pool_n) pthread_cond_signal(&cv_done);
    }
}
static void ensure(int n) {
    pool_n = n;
    for (int i = 0; i < n; i++) pthread_create(&threads[i], NULL, worker, (void*)(intptr_t)i);
}
static void run(void) {
    pthread_mutex_lock(&mu);
    done_count = 0;
    start_epoch++;
    pthread_cond_broadcast(&cv_start);
    while (done_count < pool_n) pthread_cond_wait(&cv_done, &mu);
    pthread_mutex_unlock(&mu);
}
int main() {
    unsigned char *pt = aligned_alloc(64, N);
    unsigned char *ct = aligned_alloc(64, N);
    FILE *f = fopen("/dev/urandom","rb"); fread(pt,1,N,f); fclose(f);
    unsigned char pkey[32] = {0};
    void *pctx = aligned_alloc(64, 4096);
    unsigned char mac[16];
    int reps = 6;
    for (int nt = 1; nt <= 6; nt++) {
        ensure(nt);
        /* split */
        size_t blocks = (N/64)/nt;
        for (int i = 0; i < nt; i++) {
            size_t off = i * blocks * 64;
            jobs[i].out = ct+off; jobs[i].in = pt+off;
            jobs[i].len = (i==nt-1)?(N-off):blocks*64;
            memset(jobs[i].key, 0, 32);
            jobs[i].counter[0] = 1 + (unsigned)(off/64);
            jobs[i].counter[1]=1; jobs[i].counter[2]=2; jobs[i].counter[3]=3;
        }
        /* warmup */
        run();
        double t0 = now();
        for (int r = 0; r < reps; r++) {
            run();
            Poly1305_Init(pctx, pkey);
            Poly1305_Update(pctx, ct, N);
            Poly1305_Final(pctx, mac);
        }
        double t1 = now();
        printf("%d threads chacha+poly: %.2f ms  %.0f MB/s\n", nt, (t1-t0)/reps*1000, N/((t1-t0)/reps)/1e6);
        /* don't restart pool; this leaks extra threads if we call ensure again. break structure: only test one nt per process. */
        break;
    }
    return 0;
}
EOF
