{"command":"cd "$HOME/chacha_bench" && cat > p64.c << 'EOF'
/* 64-bit Poly1305, one block at a time, for throughput measurement */
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef __uint128_t u128;

static inline void add_block(u128 *h, uint64_t *h2, const unsigned char *m, uint64_t r0, uint64_t r1, uint64_t r2, uint64_t s1) {
    uint64_t t0, t1;
    memcpy(&t0, m, 8);
    memcpy(&t1, m+8, 8);
    /* h += m || 1 */
    u128 h0 = *h;
    uint64_t h0_lo = (uint64_t)h0;
    uint64_t h0_hi = (uint64_t)(h0 >> 64);
    uint64_t hh2 = *h2;
    /* add */
    unsigned __int128 sum = (unsigned __int128)h0_lo + t0;
    h0_lo = (uint64_t)sum;
    sum = (unsigned __int128)h0_hi + t1 + (uint64_t)(sum >> 64);
    h0_hi = (uint64_t)sum;
    hh2 += 1 + (uint64_t)(sum >> 64);

    /* h *= r, r = r0 + r1*2^64 + r2*2^130, with r2 being 0 or small (the hibit is in a separate 2-bit)
       Standard representation: r is 130-bit? Poly1305 r is 128-bit clamped, so r2 (bits above 128) is 0
       and the +1 of the message provides the 2^128 term.
       We store h as 130-bit: h0 (128 bit) + h2 (2 bit, actually can be a bit more before reduction).
    */
    /* h * r:
       (h0 + h2*2^128) * (r0 + r1*2^64) 
       = h0*r0 + h0*r1*2^64 + h2*r0*2^128 + h2*r1*2^192
    */
    uint64_t h_lo = h0_lo, h_hi = h0_hi;
    /* h0 * r0 */
    unsigned __int128 p0 = (unsigned __int128)h_lo * r0;
    unsigned __int128 p1 = (unsigned __int128)h_hi * r0;
    unsigned __int128 p2 = (unsigned __int128)h_lo * r1;
    unsigned __int128 p3 = (unsigned __int128)h_hi * r1;
    /* plus h2 * r shifted by 128 */
    unsigned __int128 p4 = (unsigned __int128)hh2 * r0; /* at 2^128 */
    unsigned __int128 p5 = (unsigned __int128)hh2 * r1; /* at 2^192 */

    /* accumulate into 5x64 roughly */
    uint64_t z0 = (uint64_t)p0;
    unsigned __int128 acc1 = (p0 >> 64) + (uint64_t)p1 + (uint64_t)p2;
    uint64_t z1 = (uint64_t)acc1;
    unsigned __int128 acc2 = (acc1 >> 64) + (p1 >> 64) + (p2 >> 64) + (uint64_t)p3 + (uint64_t)p4;
    uint64_t z2 = (uint64_t)acc2;
    unsigned __int128 acc3 = (acc2 >> 64) + (p3 >> 64) + (p4 >> 64) + (uint64_t)p5;
    uint64_t z3 = (uint64_t)acc3;
    uint64_t z4 = (uint64_t)(acc3 >> 64) + (uint64_t)(p5 >> 64);

    /* reduce mod 2^130-5: bits above 130 multiply by 5.
       z0 (64) + z1 (64) = low 128, then z2 low 2 bits stay, rest *5.
       value = z0 + z1<<64 + z2<<128 + z3<<192 + z4<<256
       2^130 ≡ 5, so bits from position 130:
       low130 = z0 + (z1<<64) + (z2 & 3)<<128
       high = (z2>>2) + z3<<62 + z4<<126
       result = low130 + 5*high
    */
    uint64_t lo = z0;
    uint64_t hi = z1;
    uint64_t hibits = (z2 & 3);
    /* high part starting at bit 130, expressed as integer whose *5 adds at bit 0 */
    /* 5 * ((z2>>2) + z3<<62 + z4<<126) */
    unsigned __int128 high = (unsigned __int128)(z2 >> 2) + ((unsigned __int128)z3 << 62) + ((unsigned __int128)z4 << 126);
    unsigned __int128 five = high * 5;
    unsigned __int128 sumlo = (unsigned __int128)lo + (uint64_t)five;
    lo = (uint64_t)sumlo;
    unsigned __int128 sumhi = (unsigned __int128)hi + (uint64_t)(sumlo >> 64) + (uint64_t)(five >> 64);
    hi = (uint64_t)sumhi;
    hibits += (uint64_t)(sumhi >> 64);
    /* hibits may be >= 4, fold again */
    if (hibits >= 4) {
        uint64_t extra = hibits >> 2;
        hibits &= 3;
        sumlo = (unsigned __int128)lo + extra * 5;
        lo = (uint64_t)sumlo;
