#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <immintrin.h>

/* 2-way parallel Poly1305 using AVX2 64-bit muls.
   Each lane processes a 16-byte block, then we combine? For throughput of independent
   accumulators this measures raw mul throughput, not a correct single MAC.
   We do 4 independent 16-byte accumulators per iteration (4 blocks) to expose ILP,
   then this is an UPPER bound on a 4-way delayed-reduction poly1305. */

static inline void mul_acc(unsigned __int128 *h, uint64_t m0, uint64_t m1, uint64_t r0, uint64_t r1) {
    unsigned __int128 H = *h + (((unsigned __int128)m1 << 64) | m0) + ((unsigned __int128)1 << 128);
    uint64_t h0 = (uint64_t)H;
    uint64_t h1 = (uint64_t)(H >> 64);
    uint64_t h2 = (uint64_t)(H >> 128); /* 0 or 1 typically, but after add can be more */
    /* actually H fits in 130 bits before this? we add 129-bit message to previous reduced h */
    unsigned __int128 p0 = (unsigned __int128)h0 * r0;
    unsigned __int128 p1 = (unsigned __int128)h1 * r0;
    unsigned __int128 p2 = (unsigned __int128)h0 * r1;
    unsigned __int128 p3 = (unsigned __int128)h1 * r1;
    unsigned __int128 p4 = (unsigned __int128)h2 * r0;
    unsigned __int128 p5 = (unsigned __int128)h2 * r1;
    uint64_t z0 = (uint64_t)p0;
    unsigned __int128 a1 = (p0>>64) + (uint64_t)p1 + (uint64_t)p2;
    uint64_t z1 = (uint64_t)a1;
    unsigned __int128 a2 = (a1>>64) + (p1>>64) + (p2>>64) + (uint64_t)p3 + (uint64_t)p4;
    uint64_t z2 = (uint64_t)a2;
    unsigned __int128 a3 = (a2>>64) + (p3>>64) + (p4>>64) + (uint64_t)p5;
    uint64_t z3 = (uint64_t)a3;
    uint64_t z4 = (uint64_t)(a3>>64) + (uint64_t)(p5>>64);
    unsigned __int128 high = (unsigned __int128)(z2>>2) + ((unsigned __int128)z3<<62) + ((unsigned __int128)z4<<126);
    unsigned __int128 five = high * 5;
    unsigned __int128 s0 = (unsigned __int128)z0 + (uint64_t)five;
    unsigned __int128 s1 = (unsigned __int128)z1 + (uint64_t)(s0>>64) + (uint64_t)(five>>64);
    uint64_t hib = (z2 & 3) + (uint64_t)(s1>>64);
    if (hib >= 4) {
        uint64_t extra = hib >> 2;
        hib &= 3;
        s0 = (uint64_t)s0 + extra * 5;
        s1 = (uint64_t)s1 + (uint64_t)(s0>>64);
        hib += (uint64_t)(s1>>64);
    }
    *h = ((unsigned __int128)(uint64_t)s1 << 64) | (uint64_t)s0 | ((unsigned __int128)hib << 128);
}

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    size_t N = 40*1024*1024;
    unsigned char *buf = aligned_alloc(64, N);
    memset(buf, 1, N);
    uint64_t r0 = 0x0ffffffc0ffffffcULL;
    uint64_t r1 = 0x0ffffffc0ffffffcULL;
    int reps = 3;
    double t0 = now();
    unsigned __int128 h[4] = {0,0,0,0};
    for (int r = 0; r < reps; r++) {
        h[0]=h[1]=h[2]=h[3]=0;
        for (size_t i = 0; i < N; i += 64) {
            uint64_t m0,m1;
            memcpy(&m0, buf+i, 8); memcpy(&m1, buf+i+8, 8);
            mul_acc(&h[0], m0, m1, r0, r1);
            memcpy(&m0, buf+i+16, 8); memcpy(&m1, buf+i+24, 8);
            mul_acc(&h[1], m0, m1, r0, r1);
            memcpy(&m0, buf+i+32, 8); memcpy(&m1, buf+i+40, 8);
            mul_acc(&h[2], m0, m1, r0, r1);
            memcpy(&m0, buf+i+48, 8); memcpy(&m1, buf+i+56, 8);
            mul_acc(&h[3], m0, m1, r0, r1);
        }
    }
    double t1 = now();
    printf("4-way ILP poly: %.2f ms  %.0f MB/s\n", (t1-t0)/reps*1000, N/((t1-t0)/reps)/1e6);

    /* AVX2 vpmuludq throughput: 4 independent 32x32->64 muls per instruction, 
       a 26-bit limb poly needs ~8 such muls per 16 bytes if done carefully... measure raw */
    __m256i a = _mm256_set1_epi32(0x0ffffffc);
    __m256i b = _mm256_set1_epi32(0x12345678);
    __m256i acc = _mm256_setzero_si256();
    t0 = now();
    size_t iters = N / 16; /* pretend each iter is one 16-byte block worth of 8 muls? do 8 muls */
    for (int r = 0; r < reps; r++) {
        for (size_t i = 0; i < iters; i++) {
            acc = _mm256_add_epi64(acc, _mm256_mul_epu32(a, b));
            acc = _mm256_add_epi64(acc, _mm256_mul_epu32(a, b));
        }
    }
    t1 = now();
    printf("raw vpmuludq 8/block: %.2f ms  %.0f MB/s equiv  sink=%llx\n", (t1-t0)/reps*1000, N/((t1-t0)/reps)/1e6, (unsigned long long)_mm256_extract_epi64(acc, 0));
    return 0;
}
