{"command":"cd "$HOME/chacha_bench" && cat > poly_ref.c << 'EOF'
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <openssl/evp.h>

size_t Poly1305_ctx_size(void);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

static void poly_ossl(const unsigned char *m, size_t n, const unsigned char key[32], unsigned char mac[16]) {
    void *ctx = aligned_alloc(64, 4096);
    memset(ctx, 0, 4096);
    Poly1305_Init(ctx, key);
    Poly1305_Update(ctx, m, n);
    Poly1305_Final(ctx, mac);
    free(ctx);
}

/* Our implementation */
typedef struct { unsigned __int128 h; uint32_t h2; } st;

static void process(st *s, const unsigned char *m, int hibit, uint64_t r0, uint64_t r1) {
    uint64_t t0, t1;
    memcpy(&t0, m, 8);
    memcpy(&t1, m+8, 8);
    unsigned __int128 H = s->h;
    uint64_t h0 = (uint64_t)H;
    uint64_t h1 = (uint64_t)(H >> 64);
    uint64_t h2 = s->h2;
    unsigned __int128 sum = (unsigned __int128)h0 + t0;
    h0 = (uint64_t)sum;
    sum = (unsigned __int128)h1 + t1 + (uint64_t)(sum >> 64);
    h1 = (uint64_t)sum;
    h2 += hibit + (uint64_t)(sum >> 64);

    unsigned __int128 p0 = (unsigned __int128)h0 * r0;
    unsigned __int128 p1 = (unsigned __int128)h1 * r0;
    unsigned __int128 p2 = (unsigned __int128)h0 * r1;
    unsigned __int128 p3 = (unsigned __int128)h1 * r1;
    unsigned __int128 p4 = (unsigned __int128)h2 * r0;
    unsigned __int128 p5 = (unsigned __int128)h2 * r1;

    uint64_t z0 = (uint64_t)p0;
    unsigned __int128 a1 = (p0 >> 64) + (uint64_t)p1 + (uint64_t)p2;
    uint64_t z1 = (uint64_t)a1;
    unsigned __int128 a2 = (a1 >> 64) + (p1 >> 64) + (p2 >> 64) + (uint64_t)p3 + (uint64_t)p4;
    uint64_t z2 = (uint64_t)a2;
    unsigned __int128 a3 = (a2 >> 64) + (p3 >> 64) + (p4 >> 64) + (uint64_t)p5;
    uint64_t z3 = (uint64_t)a3;
    uint64_t z4 = (uint64_t)(a3 >> 64) + (uint64_t)(p5 >> 64);

    unsigned __int128 high = (unsigned __int128)(z2 >> 2) + ((unsigned __int128)z3 << 62) + ((unsigned __int128)z4 << 126);
    unsigned __int128 five = high * 5;
    unsigned __int128 s0 = (unsigned __int128)z0 + (uint64_t)five;
    unsigned __int128 s1 = (unsigned __int128)z1 + (uint64_t)(s0 >> 64) + (uint64_t)(five >> 64);
    uint64_t hib = (z2 & 3) + (uint64_t)(s1 >> 64);
    while (hib >= 4) {
        uint64_t extra = hib >> 2;
        hib &= 3;
        s0 = (uint64_t)s0 + extra * 5;
        s1 = (uint64_t)s1 + (uint64_t)(s0 >> 64);
        hib += (uint64_t)(s1 >> 64);
    }
    s->h = ((unsigned __int128)(uint64_t)s1 << 64) | (uint64_t)s0;
    s->h2 = (uint32_t)hib;
}

static void poly_ours(const unsigned char *m, size_t n, const unsigned char key[32], unsigned char mac[16]) {
    uint64_t r0, r1, s0, s1;
    memcpy(&r0, key, 8);
    memcpy(&r1, key+8, 8);
    memcpy(&s0, key+16, 8);
    memcpy(&s1, key+24, 8);
    r0 &= 0x0ffffffc0fffffffULL;
    r1 &= 0x0ffffffc0ffffffcULL;
    st s = {0, 0};
    while (n >= 16) {
        process(&s, m, 1, r0, r1);
        m += 16; n -= 16;
    }
    if (n) {
        unsigned char block[16] = {0};
        memcpy(block, m, n);
        block[n] = 1;
        process(&s, block, 0, r0, r1);
    }
    /* final reduction fully into 0..p-1 */
    unsigned __int128 h = s.h;
    uint64_t h2 = s.h2;
    /* compare with p = 2^130-5 */
    /* h >= p iff h2 > 3 or (h2==3 && h >= 2^128-5) i.e. h + 5 >= 2^128 */
    uint64_t h0 = (uint64_t)h, h1 = (uint64_t)(h >> 64);
    int ge = 0;
    if (h2 > 3) ge = 1;
    else if (h2 == 3) {
        unsigned __int128 t = (unsigned __int128)h0 + 5;
        if ((uint64_t)(t >> 64) + h1 < h1 || ((uint64_t)(t >> 64) + h1) >> 64) {
            /* h0+5 overflowed into beyond h1? simpler: h + 5 >= 2^128 */
        }
        unsigned __int128 sum = h + 5;
        if (sum < h) ge = 1; /* overflow means h >= 2^128-5 */
    }
    if (ge) {
        /* subtract p: h = h - 2^130 + 5 = h + 5, drop bit 130+ */
        unsigned __int128 sum = h + 5;
        h0 = (uint64_t)sum;
        h1 = (uint64_t)(sum >> 64);
        /* if h2>3 this is incomplete; shouldn't happen after our reduction */
    }
    unsigned __int128 sum = (unsigned __int128)h0 + s0;
    uint64_t o0 = (uint64_t)sum;
    uint64_t o1 = h1 + s1 + (uint64_t)(sum >> 64);
    memcpy(mac, &o0, 8);
    memcpy(mac+8, &o1, 8);
}

int main() {
    unsigned char key[32], msg[64];
    FILE *f = fopen("/dev/urandom","rb");
    fread(key,1,32,f);
    fread(msg,1,64,f);
    fclose(f);
    unsigned char a[16], b[16];
    for (size_t n = 0; n <= 64; n++) {
        poly_ossl(msg, n, key, a);
        poly_ours(msg, n, key, b);
        if (memcmp(a,b,16)!=0) {
            printf("MISMATCH n=%zu\n ossl ", n);
            for (int i=0;i<16;i++) printf("%02x", a[i]);
            printf("\n ours ");
            for (int i=0;i<16;i++) printf("%02x", b[i]);
            printf("\n");
            return 1;
        }
    }
    /* large */
    size_t N = 100000;
    unsigned char *big = malloc(N);
    fread(big, 1, N, f); /* f closed, ignore */
    FILE *g = fopen("/dev/urandom","rb"); fread(big,1,N,g); fclose(g);
    poly_ossl(big, N, key, a);
    poly_ours(big, N, key, b);
    printf(memcmp(a,b,16)==0 ? "large OK\n" : "large FAIL\n");
    printf("all small OK\n");
    return 0;
}
EOF
cc -O2 -o poly_ref poly_ref.c -L/usr/local/lib -lcrypto && ./poly_ref"}

{"command":"cd "$HOME/chacha_bench" && cat > poly4.c << 'EOF'
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
size_t Poly1305_ctx_size(void);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

static inline void mul_r(uint64_t h0, uint64_t h1, uint64_t h2,
                         uint64_t r0, uint64_t r1,
                         uint64_t *o0, uint64_t *o1, uint64_t *o2) {
    unsigned __int128 p0 = (unsigned __int128)h0 * r0;
    unsigned __int128 p1 = (unsigned __int128)h1 * r0;
    unsigned __int128 p2 = (unsigned __int128)h0 * r1;
    unsigned __int128 p3 = (unsigned __int128)h1 * r1;
    unsigned __int128 p4 = (unsigned __int128)h2 * r0;
    unsigned __int128 p5 = (unsigned __int128)h2 * r1;
    uint64_t z0 = (uint64_t)p0;
    unsigned __int128 a1 = (p0 >> 64) + (uint64_t)p1 + (uint64_t)p2;
    uint64_t z1 = (uint64_t)a1;
    unsigned __int128 a2 = (a1 >> 64) + (p1 >> 64) + (p2 >> 64) + (uint64_t)p3 + (uint64_t)p4;
    uint64_t z2 = (uint64_t)a2;
    unsigned __int128 a3 = (a2 >> 64) + (p3 >> 64) + (p4 >> 64) + (uint64_t)p5;
    uint64_t z3 = (uint64_t)a3;
    uint64_t z4 = (uint64_t)(a3 >> 64) + (uint64_t)(p5 >> 64);
    unsigned __int128 high = (unsigned __int128)(z2 >> 2) + ((unsigned __int128)z3 << 62) + ((unsigned __int128)z4 << 126);
    unsigned __int128 five = high * 5;
    unsigned __int128 s0 = (unsigned __int128)z0 + (uint64_t)five;
    unsigned __int128 s1 = (unsigned __int128)z1 + (uint64_t)(s0 >> 64) + (uint64_t)(five >> 64);
    uint64_t hib = (z2 & 3) + (uint64_t)(s1 >> 64);
    if (hib >= 4) {
        uint64_t extra = hib >> 2;
        hib &= 3;
        s0 = (uint64_t)s0 + extra * 5;
        s1 = (uint64_t)s1 + (uint64_t)(s0 >> 64);
        hib += (uint64_t)(s1 >> 64);
    }
    *o0 = (uint64_t)s0; *o1 = (uint64_t)s1; *o2 = hib;
}

/* add message block (with hibit) then multiply by r */
static inline void acc_mul(uint64_t *h0, uint64_t *h1, uint64_t *h2,
                           uint64_t m0, uint64_t m1, uint64_t hibit,
                           uint64_t r0, uint64_t r1) {
    unsigned __int128 sum = (unsigned __int128)(*h0) + m0;
    uint64_t a0 = (uint64_t)sum;
    sum = (unsigned __int128)(*h1) + m1 + (uint64_t)(sum >> 64);
    uint64_t a1 = (uint64_t)sum;
    uint64_t a2 = *h2 + hibit + (uint64_t)(sum >> 64);
    mul_r(a0, a1, a2, r0, r1, h0, h1, h2);
}

/* h = h + g * r^k, both in (130-bit) partially reduced form. g is a block accumulator. */
static inline void add_scaled(uint64_t *h0, uint64_t *h1, uint64_t *h2,
                              uint64_t g0, uint64_t g1, uint64_t g2,
                              uint64_t rk0, uint64_t rk1) {
    /* compute g * r^k */
    uint64_t p0, p1, p2;
    mul_r(g0, g1, g2, rk0, rk1, &p0, &p1, &p2);
    unsigned __int128 sum = (unsigned __int128)(*h0) + p0;
    uint64_t a0 = (uint64_t)sum;
    sum = (unsigned __int128)(*h1) + p1 + (uint64_t)(sum >> 64);
    uint64_t a1 = (uint64_t)sum;
    uint64_t a2 = *h2 + p2 + (uint64_t)(sum >> 64);
    /* partial reduce */
    if (a2 >= 4) {
        uint64_t extra = a2 >> 2;
        a2 &= 3;
        sum = (unsigned __int128)a0 + extra * 5;
        a0 = (uint64_t)sum;
        sum = (unsigned __int128)a1 + (uint64_t)(sum >> 64);
        a1 = (uint64_t)sum;
        a2 += (uint64_t)(sum >> 64);
    }
    *h0 = a0; *h1 = a1; *h2 = a2;
}

static void poly_fast(const unsigned char *m, size_t n, const unsigned char key[32], unsigned char mac[16]) {
    uint64_t r0, r1, s0, s1;
    memcpy(&r0, key, 8);
    memcpy(&r1, key+8, 8);
    memcpy(&s0, key+16, 8);
    memcpy(&s1, key+24, 8);
    r0 &= 0x0ffffffc0fffffffULL;
    r1 &= 0x0ffffffc0ffffffcULL;

    /* r^2, r^4 */
    uint64_t r2_0, r2_1, r2_2, r4_0, r4_1, r4_2;
    mul_r(r0, r1, 0, r0, r1, &r2_0, &r2_1, &r2_2);
    /* r^2 should have h2==0 since r < 2^124. fold if not */
    if (r2_2) {
        /* shouldn't really happen for clamped r; fold */
        unsigned __int128 sum = (unsigned __int128)r2_0 + (r2_2) * 5; /* r2_2 is bits at 130, *5 */
        /* wait r2_2 is the 2^128 coefficient not 2^130. Handle properly: value = r2_0 + r2_1<<64 + r2_2<<128
           bits above 130 = r2_2>>2, low = r2_0 + r2_1<<64 + (r2_2&3)<<128 */
        uint64_t extra = r2_2 >> 2;
        r2_2 &= 3;
        sum = (unsigned __int128)r2_0 + extra * 5;
        r2_0 = (uint64_t)sum;
        sum = (unsigned __int128)r2_1 + (uint64_t)(sum >> 64);
        r2_1 = (uint64_t)sum;
        r2_2 += (uint64_t)(sum >> 64);
    }
    mul_r(r2_0, r2_1, r2_2, r2_0, r2_1, &r4_0, &r4_1, &r4_2);

    uint64_t h0=0,h1=0,h2=0;
    uint64_t g0=0,g1=0,g2=0, gg0=0,gg1=0,gg2=0, ggg0=0,ggg1=0,ggg2=0;

    /* 4 independent accumulators, each multiplied by r^4 per step, stride 64 bytes */
    while (n >= 64) {
        uint64_t m0, m1;
        memcpy(&m0, m, 8); memcpy(&m1, m+8, 8);
        acc_mul(&h0, &h1, &h2, m0, m1, 1, r4_0, r4_1);
        memcpy(&m0, m+16, 8); memcpy(&m1, m+24, 8);
        acc_mul(&g0, &g1, &g2, m0, m1, 1, r4_0, r4_1);
        memcpy(&m0, m+32, 8); memcpy(&m1, m+40, 8);
        acc_mul(&gg0, &gg1, &gg2, m0, m1, 1, r4_0, r4_1);
        memcpy(&m0, m+48, 8); memcpy(&m1, m+56, 8);
        acc_mul(&ggg0, &ggg1, &ggg2, m0, m1, 1, r4_0, r4_1);
        m += 64; n -= 64;
    }
    /* combine: h_total = h*r^3 + g*r^2 + gg*r + ggg */
    uint64_t r3_0, r3_1, r3_2;
    mul_r(r2_0, r2_1, r2_2, r0, r1, &r3_0, &r3_1, &r3_2);
    /* scale */
    uint64_t t0,t1,t2;
    mul_r(h0, h1, h2, r3_0, r3_1, &t0, &t1, &t2);
    h0=t0; h1=t1; h2=t2;
    mul_r(g0, g1, g2, r2_0, r2_1, &t0, &t1, &t2);
    /* add */
    {
        unsigned __int128 sum = (unsigned __int128)h0 + t0;
        h0 = (uint64_t)sum;
        sum = (unsigned __int128)h1 + t1 + (uint64_t)(sum>>64);
        h1 = (uint64_t)sum;
        h2 = h2 + t2 + (uint64_t)(sum>>64);
    }
    mul_r(gg0, gg1, gg2, r0, r1, &t0, &t1, &t2);
    {
        unsigned __int128 sum = (unsigned __int128)h0 + t0;
        h0 = (uint64_t)sum;
        sum = (unsigned __int128)h1 + t1 + (uint64_t)(sum>>64);
        h1 = (uint64_t)sum;
        h2 = h2 + t2 + (uint64_t)(sum>>64);
    }
    {
        unsigned __int128 sum = (unsigned __int128)h0 + ggg0;
        h0 = (uint64_t)sum;
        sum = (unsigned __int128)h1 + ggg1 + (uint64_t)(sum>>64);
        h1 = (uint64_t)sum;
        h2 = h2 + ggg2 + (uint64_t)(sum>>64);
    }
    if (h2 >= 4) {
        uint64_t extra = h2 >> 2; h2 &= 3;
        unsigned __int128 sum = (unsigned __int128)h0 + extra*5;
        h0 = (uint64_t)sum;
        sum = (unsigned __int128)h1 + (uint64_t)(sum>>64);
        h1 = (uint64_t)sum;
        h2 += (uint64_t)(sum>>64);
    }

    /* tail */
    while (n >= 16) {
        uint64_t m0, m1;
        memcpy(&m0, m, 8); memcpy(&m1, m+8, 8);
        acc_mul(&h0, &h1, &h2, m0, m1, 1, r0, r1);
        m += 16; n -= 16;
    }
    if (n) {
        unsigned char block[16] = {0};
        memcpy(block, m, n);
        block[n] = 1;
        uint64_t m0, m1;
        memcpy(&m0, block, 8); memcpy(&m1, block+8, 8);
        acc_mul(&h0, &h1, &h2, m0, m1, 0, r0, r1);
    }

    /* final */
    unsigned __int128 H = ((unsigned __int128)h1 << 64) | h0;
    int ge = 0;
    if (h2 > 3) ge = 1;
    else if (h2 == 3) {
        unsigned __int128 sum = H + 5;
        if (sum < H) ge = 1;
    }
    uint64_t o0 = h0, o1 = h1;
    if (ge) {
        unsigned __int128 sum = H + 5;
        o0 = (uint64_t)sum; o1 = (uint64_t)(sum >> 64);
    }
    unsigned __int128 sum = (unsigned __int128)o0 + s0;
    uint64_t f0 = (uint64_t)sum;
    uint64_t f1 = o1 + s1 + (uint64_t)(sum >> 64);
    memcpy(mac, &f0, 8);
    memcpy(mac+8, &f1, 8);
}

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    unsigned char key[32];
    FILE *g = fopen("/dev/urandom","rb");
    fread(key,1,32,g);
    size_t N = 40*1024*1024;
    unsigned char *buf = aligned_alloc(64, N);
    fread(buf,1,N,g);
    fclose(g);
    unsigned char a[16], b[16];
    void *ctx = aligned_alloc(64, 4096);
    memset(ctx,0,4096);
    Poly1305_Init(ctx, key);
    Poly1305_Update(ctx, buf, N);
    Poly1305_Final(ctx, a);
    poly_fast(buf, N, key, b);
    printf(memcmp(a,b,16)==0 ? "MATCH\n" : "MISMATCH\n");
    if (memcmp(a,b,16)!=0) {
        for (int i=0;i<16;i++) printf("%02x", a[i]); printf("\n");
        for (int i=0;i<16;i++) printf("%02x", b[i]); printf("\n");
    }
    int reps = 5;
    double t0 = now();
    for (int i = 0; i < reps; i++) poly_fast(buf, N, key, b);
    double t1 = now();
    printf("poly4: %.2f ms  %.0f MB/s\n", (t1-t0)/reps*1000, N/((t1-t0)/reps)/1e6);
    t0 = now();
    for (int i = 0; i < reps; i++) {
        Poly1305_Init(ctx, key);
        Poly1305_Update(ctx, buf, N);
        Poly1305_Final(ctx, a);
    }
    t1 = now();
    printf("ossl: %.2f ms  %.0f MB/s\n", (t1-t0)/reps*1000, N/((t1-t0)/reps)/1e6);
    return 0;
}
