    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}
#define N (40u*1024u*1024u)
#define CHUNK (1u<<20) /* 1 MB */

typedef struct {
    unsigned char *out, *in;
    size_t off, len;
    unsigned int key[8];
    unsigned int counter[4];
    int go, done, stop;
    pthread_mutex_t mu;
    pthread_cond_t cv;
} worker_t;

static void *wfn(void *arg) {
    worker_t *w = arg;
    pthread_mutex_lock(&w->mu);
    for (;;) {
        while (!w->go && !w->stop) pthread_cond_wait(&w->cv, &w->mu);
        if (w->stop) { pthread_mutex_unlock(&w->mu); return NULL; }
        w->go = 0;
        size_t off = w->off, len = w->len;
        pthread_mutex_unlock(&w->mu);
        unsigned int c[4] __attribute__((aligned(32)));
        unsigned int k[8] __attribute__((aligned(32)));
        memcpy(k, w->key, 32);
        memcpy(c, w->counter, 16);
        c[0] = 1 + (unsigned)(off / 64);
        ChaCha20_ctr32(w->out + off, w->in + off, len, k, c);
        pthread_mutex_lock(&w->mu);
        w->done = 1;
        pthread_cond_signal(&w->cv);
    }
}

int main() {
    int nthreads = 3;
    unsigned char *pt = aligned_alloc(64, N);
    unsigned char *ct = aligned_alloc(64, N);
    FILE *f = fopen("/dev/urandom","rb"); fread(pt,1,N,f); fclose(f);
    unsigned char pkey[32] = {0};
    void *pctx = aligned_alloc(64, 4096);
    unsigned char mac[16];

    worker_t ws[4];
    pthread_t th[4];
    for (int i = 0; i < nthreads; i++) {
        memset(&ws[i], 0, sizeof(ws[i]));
        pthread_mutex_init(&ws[i].mu, NULL);
        pthread_cond_init(&ws[i].cv, NULL);
        ws[i].out = ct; ws[i].in = pt;
        pthread_create(&th[i], NULL, wfn, &ws[i]);
    }

    int reps = 5;
    /* warmup */
    size_t chunk = N / nthreads;
    /* round chunk down to 64 */
    chunk = (chunk / 64) * 64;
    for (int i = 0; i < nthreads; i++) {
        size_t off = i * chunk;
        size_t len = (i == nthreads-1) ? (N - off) : chunk;
        pthread_mutex_lock(&ws[i].mu);
        ws[i].off = off; ws[i].len = len; ws[i].done = 0; ws[i].go = 1;
        pthread_cond_signal(&ws[i].cv);
        pthread_mutex_unlock(&ws[i].mu);
    }
    for (int i = 0; i < nthreads; i++) {
        pthread_mutex_lock(&ws[i].mu);
        while (!ws[i].done) pthread_cond_wait(&ws[i].cv, &ws[i].mu);
        pthread_mutex_unlock(&ws[i].mu);
    }

    double t0 = now();
    for (int r = 0; r < reps; r++) {
        for (int i = 0; i < nthreads; i++) {
            size_t off = i * chunk;
            size_t len = (i == nthreads-1) ? (N - off) : chunk;
            pthread_mutex_lock(&ws[i].mu);
            ws[i].off = off; ws[i].len = len; ws[i].done = 0; ws[i].go = 1;
            pthread_cond_signal(&ws[i].cv);
            pthread_mutex_unlock(&ws[i].mu);
        }
        for (int i = 0; i < nthreads; i++) {
            pthread_mutex_lock(&ws[i].mu);
            while (!ws[i].done) pthread_cond_wait(&ws[i].cv, &ws[i].mu);
            pthread_mutex_unlock(&ws[i].mu);
        }
        Poly1305_Init(pctx, pkey);
        Poly1305_Update(pctx, ct, N);
        Poly1305_Final(pctx, mac);
    }
    double t1 = now();
    printf("3 workers + poly serial: %.2f ms\n", (t1-t0)/reps*1000);

    /* pipeline: while workers encrypt chunk i+1, main poly's chunk i. Use double buffer. */
    unsigned char *ct2 = aligned_alloc(64, N);
    /* We'll do: workers fill ct, main polys ct of previous iteration into a running state.
       Within one message: split into 4 chunks of 10MB. 
       Phase: encrypt chunk0 (3 threads), then for k=1..3: encrypt chunk k while poly chunk k-1, then poly last.
    */
    size_t C = 4;
    size_t csz = N / C; /* 10MB, divisible by 64 */
    t0 = now();
    for (int r = 0; r < reps; r++) {
        /* encrypt chunk 0 */
        size_t sub = csz / nthreads;
        sub = (sub/64)*64;
        for (int i = 0; i < nthreads; i++) {
            size_t off = i * sub;
            size_t len = (i == nthreads-1) ? (csz - off) : sub;
            pthread_mutex_lock(&ws[i].mu);
            ws[i].off = off; ws[i].len = len; ws[i].done = 0; ws[i].go = 1;
            pthread_cond_signal(&ws[i].cv);
            pthread_mutex_unlock(&ws[i].mu);
        }
        for (int i = 0; i < nthreads; i++) {
            pthread_mutex_lock(&ws[i].mu);
            while (!ws[i].done) pthread_cond_wait(&ws[i].cv, &ws[i].mu);
            pthread_mutex_unlock(&ws[i].mu);
        }
        Poly1305_Init(pctx, pkey);
        for (size_t k = 1; k < C; k++) {
            size_t base = k * csz;
            for (int i = 0; i < nthreads; i++) {
                size_t off = base + i * sub;
                size_t len = (i == nthreads-1) ? (csz - i*sub) : sub;
                pthread_mutex_lock(&ws[i].mu);
                ws[i].off = off; ws[i].len = len; ws[i].done = 0; ws[i].go = 1;
                pthread_cond_signal(&ws[i].cv);
                pthread_mutex_unlock(&ws[i].mu);
            }
            Poly1305_Update(pctx, ct + (k-1)*csz, csz);
            for (int i = 0; i < nthreads; i++) {
                pthread_mutex_lock(&ws[i].mu);
                while (!ws[i].done) pthread_cond_wait(&ws[i].cv, &ws[i].mu);
                pthread_mutex_unlock(&ws[i].mu);
            }
        }
        Poly1305_Update(pctx, ct + (C-1)*csz, csz);
        Poly1305_Final(pctx, mac);
    }
    t1 = now();
    printf("pipelined 3 workers + poly: %.2f ms\n", (t1-t0)/reps*1000);
    return 0;
}
