#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
#include <immintrin.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp,
                    size_t len, const unsigned int key[8],
                    const unsigned int counter[4]);

static inline uint32_t rotl(uint32_t x, int n) { return (x << n) | (x >> (32-n)); }
#define QR(a,b,c,d) \
    a += b; d ^= a; d = rotl(d, 16); \
    c += d; b ^= c; b = rotl(b, 12); \
    a += b; d ^= a; d = rotl(d, 8); \
    c += d; b ^= c; b = rotl(b, 7);

static void chacha_block(uint32_t out[16], const uint32_t in[16]) {
    uint32_t x[16];
    memcpy(x, in, 64);
    for (int i = 0; i < 10; i++) {
        QR(x[0], x[4], x[8], x[12]);
        QR(x[1], x[5], x[9], x[13]);
        QR(x[2], x[6], x[10], x[14]);
        QR(x[3], x[7], x[11], x[15]);
        QR(x[0], x[5], x[10], x[15]);
        QR(x[1], x[6], x[11], x[12]);
        QR(x[2], x[7], x[8], x[13]);
        QR(x[3], x[4], x[9], x[14]);
    }
    for (int i = 0; i < 16; i++) out[i] = x[i] + in[i];
}

static void chacha_xor(unsigned char *dst, const unsigned char *src, size_t len,
                       const uint32_t key[8], const uint32_t counter[4]) {
    uint32_t state[16];
    state[0] = 0x61707865; state[1] = 0x3320646e; state[2] = 0x79622d32; state[3] = 0x6b206574;
    memcpy(state+4, key, 32);
    state[12] = counter[0];
    state[13] = counter[1]; state[14] = counter[2]; state[15] = counter[3];
    uint32_t block[16];
    while (len >= 64) {
        chacha_block(block, state);
        uint32_t s0, s1;
        /* xor 64 bytes */
        for (int i = 0; i < 16; i++) {
            uint32_t v;
            memcpy(&v, src + 4*i, 4);
            v ^= block[i];
            memcpy(dst + 4*i, &v, 4);
        }
        state[12]++;
        src += 64; dst += 64; len -= 64;
    }
    if (len) {
        chacha_block(block, state);
        unsigned char *b = (unsigned char*)block;
        for (size_t i = 0; i < len; i++) dst[i] = src[i] ^ b[i];
    }
}

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    size_t N = 4*1024*1024; /* 4MB to keep it short */
    unsigned char *pt = aligned_alloc(64, N);
    unsigned char *ct = aligned_alloc(64, N);
    unsigned char *ct2 = aligned_alloc(64, N);
    FILE *f = fopen("/dev/urandom","rb"); fread(pt,1,N,f); fclose(f);
    uint32_t key[8] = {0};
    uint32_t ctr[4] = {0,1,2,3};
    chacha_xor(ct, pt, N, key, ctr);
    ChaCha20_ctr32(ct2, pt, N, key, ctr);
    printf(memcmp(ct, ct2, N)==0 ? "MATCH\n" : "MISMATCH\n");
    int reps = 3;
    double t0 = now();
    for (int i = 0; i < reps; i++) chacha_xor(ct, pt, N, key, ctr);
    double t1 = now();
    printf("C chacha: %.2f ms  %.0f MB/s\n", (t1-t0)/reps*1000, N/((t1-t0)/reps)/1e6);
    t0 = now();
    for (int i = 0; i < reps; i++) ChaCha20_ctr32(ct2, pt, N, key, ctr);
    t1 = now();
    printf("asm chacha: %.2f ms  %.0f MB/s\n", (t1-t0)/reps*1000, N/((t1-t0)/reps)/1e6);
    return 0;
}
