#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef void (*blocks_fn)(void *ctx, const unsigned char *inp, size_t len, unsigned int padbit);
typedef void (*emit_fn)(void *ctx, unsigned char mac[16], const unsigned int nonce[4]);
void poly1305_init(void *ctx, const unsigned char key[32], void *funcs);

static void mul_r(uint64_t h0, uint64_t h1, uint64_t h2, uint64_t r0, uint64_t r1,
                  uint64_t *o0, uint64_t *o1, uint64_t *o2) {
    unsigned __int128 p0 = (unsigned __int128)h0 * r0;
    unsigned __int128 p1 = (unsigned __int128)h1 * r0;
    unsigned __int128 p2 = (unsigned __int128)h0 * r1;
    unsigned __int128 p3 = (unsigned __int128)h1 * r1;
    unsigned __int128 p4 = (unsigned __int128)h2 * r0;
    unsigned __int128 p5 = (unsigned __int128)h2 * r1;
    uint64_t z0 = (uint64_t)p0;
    unsigned __int128 a1 = (p0 >> 64) + (uint64_t)p1 + (uint64_t)p2;
    uint64_t z1 = (uint64_t)a1;
    unsigned __int128 a2 = (a1 >> 64) + (p1 >> 64) + (p2 >> 64) + (uint64_t)p3 + (uint64_t)p4;
    uint64_t z2 = (uint64_t)a2;
    unsigned __int128 a3 = (a2 >> 64) + (p3 >> 64) + (p4 >> 64) + (uint64_t)p5;
    uint64_t z3 = (uint64_t)a3;
    uint64_t z4 = (uint64_t)(a3 >> 64) + (uint64_t)(p5 >> 64);
    unsigned __int128 high = (unsigned __int128)(z2 >> 2) + ((unsigned __int128)z3 << 62) + ((unsigned __int128)z4 << 126);
    unsigned __int128 five = high * 5;
    unsigned __int128 s0 = (unsigned __int128)z0 + (uint64_t)five;
    unsigned __int128 s1 = (unsigned __int128)z1 + (uint64_t)(s0 >> 64) + (uint64_t)(five >> 64);
    uint64_t hib = (z2 & 3) + (uint64_t)(s1 >> 64);
    while (hib >= 4) {
        uint64_t extra = hib >> 2; hib &= 3;
        s0 = (uint64_t)s0 + extra * 5;
        s1 = (uint64_t)s1 + (uint64_t)(s0 >> 64);
        hib += (uint64_t)(s1 >> 64);
    }
    *o0 = (uint64_t)s0; *o1 = (uint64_t)s1; *o2 = hib;
}

/* r^n via binary exponentiation */
static void r_pow(uint64_t r0, uint64_t r1, uint64_t nblocks, uint64_t *o0, uint64_t *o1, uint64_t *o2) {
    uint64_t b0 = r0, b1 = r1, b2 = 0;
    uint64_t a0 = 1, a1 = 0, a2 = 0; /* identity: 1. multiplying by 1 = identity. Our mul treats h as 130-bit, r as 128. identity is h2=0,h1=0,h0=1. */
    int started = 0;
    while (nblocks) {
        if (nblocks & 1) {
            if (!started) { a0 = b0; a1 = b1; a2 = b2; started = 1; }
            else mul_r(a0, a1, a2, b0, b1, &a0, &a1, &a2);
        }
        nblocks >>= 1;
        if (nblocks) mul_r(b0, b1, b2, b0, b1, &b0, &b1, &b2);
    }
    if (!started) { a0 = 1; a1 = 0; a2 = 0; }
    *o0 = a0; *o1 = a1; *o2 = a2;
}

static void add_h(uint64_t *h0, uint64_t *h1, uint64_t *h2, uint64_t a0, uint64_t a1, uint64_t a2) {
    unsigned __int128 sum = (unsigned __int128)(*h0) + a0;
    uint64_t o0 = (uint64_t)sum;
    sum = (unsigned __int128)(*h1) + a1 + (uint64_t)(sum >> 64);
    uint64_t o1 = (uint64_t)sum;
    uint64_t o2 = *h2 + a2 + (uint64_t)(sum >> 64);
    while (o2 >= 4) {
        uint64_t extra = o2 >> 2; o2 &= 3;
        sum = (unsigned __int128)o0 + extra * 5;
        o0 = (uint64_t)sum;
        sum = (unsigned __int128)o1 + (uint64_t)(sum >> 64);
        o1 = (uint64_t)sum;
        o2 += (uint64_t)(sum >> 64);
    }
    *h0 = o0; *h1 = o1; *h2 = o2;
}

#define MAX_T 4
typedef struct {
    const unsigned char *buf;
    size_t len;
    unsigned char key[32];
    unsigned char ctx[256] __attribute__((aligned(64)));
    blocks_fn blocks;
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    void *funcs[2];
    memset(j->ctx, 0, 64);
    poly1305_init(j->ctx, j->key, funcs);
    j->blocks = funcs[0];
    j->blocks(j->ctx, j->buf, j->len, 1);
    return NULL;
}

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    size_t N = 40*1024*1024;
    unsigned char *buf = aligned_alloc(64, N);
    unsigned char key[32];
    FILE *f = fopen("/dev/urandom","rb");
    fread(key,1,32,f); fread(buf,1,N,f); fclose(f);

    /* reference single */
    unsigned char ctx[256] __attribute__((aligned(64)));
    void *funcs[2];
    memset(ctx, 0, 64);
    poly1305_init(ctx, key, funcs);
    blocks_fn blocks = funcs[0];
    emit_fn emit = funcs[1];
    blocks(ctx, buf, N, 1);
    unsigned char mac_ref[16];
    unsigned int nonce[4]; memcpy(nonce, key+16, 16);
    emit(ctx, mac_ref, nonce);

    int nt = 4;
    size_t chunk = N / nt;
    job_t jobs[4];
    pthread_t th[4];
    for (int i = 0; i < nt; i++) {
        jobs[i].buf = buf + i*chunk;
        jobs[i].len = chunk;
        memcpy(jobs[i].key, key, 32);
        pthread_create(&th[i], NULL, worker, &jobs[i]);
    }
    for (int i = 0; i < nt; i++) pthread_join(th[i], NULL);

    /* combine */
    uint64_t r0, r1;
    memcpy(&r0, ctx+0x18, 8);
    memcpy(&r1, ctx+0x20, 8);
    uint64_t H0=0, H1=0, H2=0;
    size_t blocks_per = chunk / 16;
    for (int i = 0; i < nt; i++) {
        uint64_t h0, h1, h2;
        memcpy(&h0, jobs[i].ctx, 8);
        memcpy(&h1, jobs[i].ctx+8, 8);
        memcpy(&h2, jobs[i].ctx+16, 8);
        /* this partial equals m_i * r^{blocks_per-1} + ... ; to place it we multiply by r^{blocks_after} */
        size_t after = (size_t)(nt - 1 - i) * blocks_per;
        uint64_t p0, p1, p2;
        if (after == 0) { p0 = h0; p1 = h1; p2 = h2; }
        else {
            uint64_t e0, e1, e2;
            r_pow(r0, r1, after, &e0, &e1, &e2);
            mul_r(h0, h1, h2, e0, e1, &p0, &p1, &p2);
        }
        add_h(&H0, &H1, &H2, p0, p1, p2);
    }
    /* write combined into a fresh ctx and emit */
    unsigned char ctx2[256] __attribute__((aligned(64)));
    memset(ctx2, 0, 64);
    void *funcs2[2];
    poly1305_init(ctx2, key, funcs2);
    memcpy(ctx2, &H0, 8);
    memcpy(ctx2+8, &H1, 8);
    memcpy(ctx2+16, &H2, 8);
    unsigned char mac[16];
    ((emit_fn)funcs2[1])(ctx2, mac, nonce);
    printf(memcmp(mac, mac_ref, 16)==0 ? "COMBINE MATCH\n" : "COMBINE MISMATCH\n");
    if (memcmp(mac, mac_ref, 16)) {
        for (int i=0;i<16;i++) printf("%02x", mac[i]); printf("\n");
        for (int i=0;i<16;i++) printf("%02x", mac_ref[i]); printf("\n");
        printf("H2=%llu ref h2 bytes %02x\n", (unsigned long long)H2, ctx[16]);
    }

    /* timing with persistent pool omitted; just measure combine cost + parallel with reused threads roughly */
    int reps = 5;
    double t0 = now();
    for (int r = 0; r < reps; r++) {
        for (int i = 0; i < nt; i++) pthread_create(&th[i], NULL, worker, &jobs[i]);
        for (int i = 0; i < nt; i++) pthread_join(th[i], NULL);
        H0=H1=H2=0;
        for (int i = 0; i < nt; i++) {
            uint64_t h0, h1, h2;
            memcpy(&h0, jobs[i].ctx, 8);
            memcpy(&h1, jobs[i].ctx+8, 8);
            memcpy(&h2, jobs[i].ctx+16, 8);
            size_t after = (size_t)(nt - 1 - i) * blocks_per;
            uint64_t p0, p1, p2, e0, e1, e2;
            r_pow(r0, r1, after, &e0, &e1, &e2);
            mul_r(h0, h1, h2, e0, e1, &p0, &p1, &p2);
            add_h(&H0, &H1, &H2, p0, p1, p2);
        }
    }
    double t1 = now();
    printf("parallel+combine: %.2f ms\n", (t1-t0)/reps*1000);
    return 0;
}
EOF
