    uint32_t l4 = (uint32_t)(((h1 >> 40) | (h2 << 24)) & MASK26);
    memcpy(ctx, &l0, 4);
    memcpy(ctx+4, &l1, 4);
    memcpy(ctx+8, &l2, 4);
    memcpy(ctx+12, &l3, 4);
    memcpy(ctx+16, &l4, 4);
}

