static inline void mul_mod(uint64_t h0, uint64_t h1, uint64_t h2,
                           uint64_t r0, uint64_t r1,
                           uint64_t *o0, uint64_t *o1, uint64_t *o2) {
    /* (h0+h1*2^64+h2*2^128) * (r0+r1*2^64) mod 2^130-5, h2 < 4, r < 2^124 */
    unsigned __int128 p0 = (unsigned __int128)h0 * r0;
    unsigned __int128 p1 = (unsigned __int128)h1 * r0;
    unsigned __int128 p2 = (unsigned __int128)h0 * r1;
    unsigned __int128 p3 = (unsigned __int128)h1 * r1;
    unsigned __int128 p4 = (unsigned __int128)h2 * r0;
    unsigned __int128 p5 = (unsigned __int128)h2 * r1;
