static void r_pow(uint64_t r0, uint64_t r1, uint64_t n, uint64_t *o0, uint64_t *o1, uint64_t *o2) {
    /* compute r^n. identity = 1. */
    uint64_t result0 = 1, result1 = 0, result2 = 0;
    uint64_t base0 = r0, base1 = r1, base2 = 0;
    int result_is_one = 1;
    while (n) {
        if (n & 1) {
            if (result_is_one) {
                result0 = base0; result1 = base1; result2 = base2;
                result_is_one = 0;
            } else {
                mul_mod(result0, result1, result2, base0, base1, &result0, &result1, &result2);
            }
        }
        n >>= 1;
        if (n) mul_mod(base0, base1, base2, base0, base1, &base0, &base1, &base2);
    }
    *o0 = result0; *o1 = result1; *o2 = result2;
}

/* h (base 2^64, h2<4) -> 5x26 limbs, fully reduced mod 2^130-5 */
static void h_to_limbs(uint32_t l[5], uint64_t h0, uint64_t h1, uint64_t h2) {
    /* reduce if >= 2^130-5 */
    if (h2 > 3 || (h2 == 3 && (h1 > 0xffffffffffffffffULL - 0 || 
        (((unsigned __int128)h1 << 64 | h0) + 5 < ((unsigned __int128)h1 << 64 | h0))))) {
        /* h2==3 && h+5 overflows 128 bits means h >= 2^128-5, and with h2==3 that's >= 2^130-5 */
    }
    unsigned __int128 H = ((unsigned __int128)h1 << 64) | h0;
    int ge = (h2 > 3) || (h2 == 3 && (H + 5 < H));
    if (ge) {
        unsigned __int128 sum = H + 5;
        h0 = (uint64_t)sum;
        h1 = (uint64_t)(sum >> 64);
        h2 = 0; /* 3 - 4 + carry... for h2==3, subtracting 2^130 leaves h2' = 3-4 = -1 + carry from h+5.
