    }
    l[0] = (uint32_t)(h0 & 0x3ffffff);
    l[1] = (uint32_t)((h0 >> 26) & 0x3ffffff);
    l[2] = (uint32_t)(((h0 >> 52) | (h1 << 12)) & 0x3ffffff);
    l[3] = (uint32_t)((h1 >> 14) & 0x3ffffff);
    l[4] = (uint32_t)(((h1 >> 40) | (h2 << 24)) & 0x3ffffff);
