    uint32_t l0, l1, l2, l3, l4;
    memcpy(&l0, ctx, 4); memcpy(&l1, ctx+4, 4); memcpy(&l2, ctx+8, 4);
    memcpy(&l3, ctx+12, 4); memcpy(&l4, ctx+16, 4);
    /* value = l0 + l1<<26 + l2<<52 + l3<<78 + l4<<104 */
    unsigned __int128 lo = (unsigned __int128)(l0 & 0x3ffffff)
        + ((unsigned __int128)(l1 & 0x3ffffff) << 26)
        + ((unsigned __int128)(l2 & 0x3ffffff) << 52)
        + ((unsigned __int128)(l3 & 0x3ffffff) << 78);
    uint64_t hi = (uint64_t)((unsigned __int128)(l3 & 0x3ffffff) >> 50)
        + (uint64_t)((l4 & 0x3ffffff) >> 24);
    /* l4<<104 contributes to bit 104..129. bits 128..129 = l4>>24. bits 104..127 go into lo. */
    lo += (unsigned __int128)(l4 & 0x3ffffff) << 104;
    *h0 = (uint64_t)lo;
    *h1 = (uint64_t)(lo >> 64);
    *h2 = hi;
