    EVP_EncryptInit_ex(ectx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ectx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ectx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(ectx, NULL, &outlen, aad, 32);
    EVP_EncryptUpdate(ectx, ref, &outlen, ref, N);
    EVP_EncryptFinal_ex(ectx, ref+outlen, &tmplen);
    EVP_CIPHER_CTX_ctrl(ectx, EVP_CTRL_AEAD_GET_TAG, 16, tag_ref);

    /* poly key = chacha block 0 */
    unsigned char poly_block[64] __attribute__((aligned(64)));
    memset(poly_block, 0, 64);
    unsigned int k[8] __attribute__((aligned(32)));
    unsigned int c[4] __attribute__((aligned(32)));
    memcpy(k, key, 32);
    c[0] = 0; memcpy(c+1, nonce, 12);
    ChaCha20_ctr32(poly_block, poly_block, 64, k, c);

    size_t chunk = (N / NT) & ~(size_t)63;
    for (int i = 0; i < NT; i++) {
        memset(&jobs[i], 0, sizeof jobs[i]);
        pthread_mutex_init(&jobs[i].mu, NULL);
        pthread_cond_init(&jobs[i].cv, NULL);
        jobs[i].buf = buf;
        jobs[i].off = i * chunk;
        jobs[i].len = (i == NT-1) ? (N - jobs[i].off) : chunk;
        memcpy(jobs[i].key, poly_block, 32);
        memcpy(jobs[i].chacha_key, key, 32);
        c[0] = 0; memcpy(jobs[i].counter_base+1, nonce, 12);
        pthread_create(&threads[i], NULL, worker, &jobs[i]);
    }

    /* precompute r powers. r from poly key */
    uint64_t r0, r1;
    memcpy(&r0, poly_block, 8); memcpy(&r1, poly_block+8, 8);
    r0 &= 0x0ffffffc0fffffffULL;
    r1 &= 0x0ffffffc0ffffffcULL;
    uint64_t powr[NT][3];
    powr[0][0] = 1; powr[0][1] = 0; powr[0][2] = 0;
    for (int i = 1; i < NT; i++) {
        /* blocks after chunk (NT-1-i)? we'll index by chunks-after */
        rpow(r0, r1, (jobs[0].len / 16) * i, &powr[i][0], &powr[i][1], &powr[i][2]);
    }
    /* careful: last chunk may differ in length, so chunks-after for chunk i is sum of lens of chunks i+1.. */
    /* recompute properly */
    size_t after_blocks[NT];
    size_t acc = 0;
    for (int i = NT-1; i >= 0; i--) {
        after_blocks[i] = acc;
        acc += jobs[i].len / 16;
    }
    for (int i = 0; i < NT; i++) {
        if (after_blocks[i] == 0) { powr[i][0] = 1; powr[i][1] = 0; powr[i][2] = 0; }
        else rpow(r0, r1, after_blocks[i], &powr[i][0], &powr[i][1], &powr[i][2]);
    }

    dispatch_and_wait();

    /* ciphertext check */
    if (memcmp(buf, ref, N) != 0) { printf("CIPHERTEXT MISMATCH\n"); return 1; }
    printf("ciphertext OK\n");

    uint64_t H0=0, H1=0, H2=0;
    for (int i = 0; i < NT; i++) {
        uint32_t flag; memcpy(&flag, jobs[i].ctx+0x14, 4);
        uint64_t h0,h1,h2,p0,p1,p2;
        from_ctx(jobs[i].ctx, flag != 0, &h0, &h1, &h2);
        if (after_blocks[i] == 0) { p0=h0; p1=h1; p2=h2; }
        else mul130(h0, h1, h2, powr[i][0], powr[i][1], powr[i][2], &p0, &p1, &p2);
        add130(&H0, &H1, &H2, p0, p1, p2);
    }
    /* now add aad (32 bytes = 2 blocks) BEFORE ciphertext: aad contributes aad_h * r^{nblocks_ct}
       and padding. AAD is 32 bytes, exactly 2 blocks, no pad. ct length N is multiple of 16, no pad.
       Then lengths block. */
    unsigned char actx[256] __attribute__((aligned(64)));
    void *funcs[2];
    memset(actx, 0, 64);
    poly1305_init(actx, poly_block, funcs);
    ((blocks_fn)funcs[0])(actx, aad, 32, 1);
    uint32_t flag; memcpy(&flag, actx+0x14, 4);
    uint64_t ah0, ah1, ah2;
    from_ctx(actx, flag != 0, &ah0, &ah1, &ah2);
    uint64_t e0, e1, e2;
    rpow(r0, r1, N/16, &e0, &e1, &e2);
    uint64_t p0, p1, p2;
    mul130(ah0, ah1, ah2, e0, e1, e2, &p0, &p1, &p2);
    /* total = aad_h * r^{N/16} + ct_h */
    uint64_t T0=p0, T1=p1, T2=p2;
    add130(&T0, &T1, &T2, H0, H1, H2);

    /* lengths block: le64(aad_len) || le64(ct_len), with hibit 1, then * r */
    unsigned char lens[16];
    uint64_t al = 32, cl = N;
    memcpy(lens, &al, 8); memcpy(lens+8, &cl, 8);
    uint64_t m0, m1; memcpy(&m0, lens, 8); memcpy(&m1, lens+8, 8);
    /* add message with hibit: T += m + 2^128, then * r */
    add130(&T0, &T1, &T2, m0, m1, 1);
    mul130(T0, T1, T2, r0, r1, 0, &T0, &T1, &T2);

    /* emit: fully reduce and add s */
    unsigned __int128 H = ((unsigned __int128)T1 << 64) | T0;
    if (T2 == 3 && (H + 5 < H)) {
        unsigned __int128 s = H + 5;
        T0 = (uint64_t)s; T1 = (uint64_t)(s >> 64); T2 = 0;
        H = ((unsigned __int128)T1 << 64) | T0;
    }
    uint64_t s0, s1; memcpy(&s0, poly_block+16, 8); memcpy(&s1, poly_block+24, 8);
    unsigned __int128 sum = (unsigned __int128)T0 + s0;
    uint64_t f0 = (uint64_t)sum;
    uint64_t f1 = T1 + s1 + (uint64_t)(sum >> 64);
    unsigned char tag[16];
    memcpy(tag, &f0, 8); memcpy(tag+8, &f1, 8);
    printf(memcmp(tag, tag_ref, 16)==0 ? "TAG MATCH\n" : "TAG MISMATCH\n");
    if (memcmp(tag, tag_ref, 16)) {
        for (int i=0;i<16;i++) printf("%02x", tag[i]); printf("\n");
        for (int i=0;i<16;i++) printf("%02x", tag_ref[i]); printf("\n");
    }

    /* timing: restore plaintext each iter */
    unsigned char *pt = aligned_alloc(64, N);
    memcpy(pt, buf, N); /* buf is ciphertext now; save original? we overwrote. regenerate from ref path... 
                           we lost plaintext. Just re-read. */
    f = fopen("/dev/urandom","rb"); fread(pt, 1, N, f); fclose(f);
    /* use pt as the buffer */
    for (int i = 0; i < NT; i++) jobs[i].buf = pt;
    int reps = 5;
    dispatch_and_wait(); /* warmup */
    double t0 = now();
    for (int r = 0; r < reps; r++) {
        /* restore plaintext */
        /* skip restore: chacha is involution? NO, chacha xor is involution! encrypting ciphertext gives plaintext.
           So running twice toggles. For timing we can just run on whatever is there; work is identical. */
        dispatch_and_wait();
        /* combine (cheap) */
        H0=H1=H2=0;
        for (int i = 0; i < NT; i++) {
            uint32_t fl; memcpy(&fl, jobs[i].ctx+0x14, 4);
            uint64_t h0,h1,h2,q0,q1,q2;
            from_ctx(jobs[i].ctx, fl!=0, &h0,&h1,&h2);
            if (after_blocks[i]==0) { q0=h0; q1=h1; q2=h2; }
            else mul130(h0,h1,h2, powr[i][0], powr[i][1], powr[i][2], &q0,&q1,&q2);
            add130(&H0,&H1,&H2, q0,q1,q2);
        }
    }
    double t1 = now();
    printf("full parallel enc+poly: %.2f ms  %.0f MB/s\n", (t1-t0)/reps*1000, N/((t1-t0)/reps)/1e6);

    /* EVP baseline on same buffer */
    t0 = now();
    for (int r = 0; r < reps; r++) {
        EVP_EncryptInit_ex(ectx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ectx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ectx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ectx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ectx, ref, &outlen, pt, N);
        EVP_EncryptFinal_ex(ectx, ref+outlen, &tmplen);
        EVP_CIPHER_CTX_ctrl(ectx, EVP_CTRL_AEAD_GET_TAG, 16, tag_ref);
    }
    t1 = now();
    printf("EVP: %.2f ms  %.0f MB/s\n", (t1-t0)/reps*1000, N/((t1-t0)/reps)/1e6);
    return 0;
}
