void poly1305_init(void *ctx, const unsigned char key[32], void *funcs);

static void add130(uint64_t *h0, uint64_t *h1, uint64_t *h2, uint64_t a0, uint64_t a1, uint64_t a2) {
    unsigned __int128 s = (unsigned __int128)(*h0) + a0;
    uint64_t o0 = (uint64_t)s;
    s = (unsigned __int128)(*h1) + a1 + (s >> 64);
