#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);
typedef void (*blocks_fn)(void *ctx, const unsigned char *inp, size_t len, unsigned int padbit);
void poly1305_init(void *ctx, const unsigned char key[32], void *funcs);

#define MAX_T 8
typedef struct {
    unsigned char *buf; size_t off, len;
    unsigned char key[32];
    unsigned char ctx[256] __attribute__((aligned(64)));
    unsigned int chacha_key[8];
    unsigned int counter_base[4];
    int go, done, stop;
    pthread_mutex_t mu; pthread_cond_t cv;
} job_t;
static job_t jobs[MAX_T];
static pthread_t threads[MAX_T];
static int live = 0;

static void *worker(void *arg) {
    job_t *j = arg;
    pthread_mutex_lock(&j->mu);
    for (;;) {
        while (!j->go && !j->stop) pthread_cond_wait(&j->cv, &j->mu);
        if (j->stop) { pthread_mutex_unlock(&j->mu); return NULL; }
        j->go = 0;
        unsigned char *buf = j->buf; size_t off = j->off, len = j->len;
        pthread_mutex_unlock(&j->mu);
        unsigned int k[8] __attribute__((aligned(32)));
        unsigned int c[4] __attribute__((aligned(32)));
        memcpy(k, j->chacha_key, 32);
        memcpy(c, j->counter_base, 16);
        c[0] = 1 + (unsigned)(off / 64);
        ChaCha20_ctr32(buf + off, buf + off, len, k, c);
        void *funcs[2];
        memset(j->ctx, 0, 48);
        poly1305_init(j->ctx, j->key, funcs);
        ((blocks_fn)funcs[0])(j->ctx, buf + off, len, 1);
        pthread_mutex_lock(&j->mu);
        j->done = 1;
        pthread_cond_signal(&j->cv);
