        blocks(ctx, lens, 16, 1);
        unsigned int s[4];
        memcpy(s, poly_block + 16, 16);
        emit(ctx, tag, s);
    } else {
        ensure_pool();
        size_t chunk = ((size_t)N / NT) & ~(size_t)63;
        size_t offs[NT], lens_c[NT];
        for (int i = 0; i < NT; i++) {
            offs[i] = (size_t)i * chunk;
            lens_c[i] = (i == NT - 1) ? ((size_t)N - offs[i]) : chunk;
            pthread_mutex_lock(&jobs[i].mu);
            jobs[i].ct = ct;
            jobs[i].pt = pt;
            jobs[i].off = offs[i];
            jobs[i].len = lens_c[i];
            memcpy(jobs[i].poly_key, poly_block, 32);
            memcpy(jobs[i].chacha_key, key.buf, 32);
            memset(jobs[i].counter_base, 0, 16);
            memcpy(jobs[i].counter_base + 1, nonce.buf, 12);
            jobs[i].done = 0;
            jobs[i].go = 1;
            pthread_cond_signal(&jobs[i].cv);
            pthread_mutex_unlock(&jobs[i].mu);
        }
        for (int i = 0; i < NT; i++) {
            pthread_mutex_lock(&jobs[i].mu);
            while (!jobs[i].done) pthread_cond_wait(&jobs[i].cv, &jobs[i].mu);
            pthread_mutex_unlock(&jobs[i].mu);
        }

        uint64_t r0, r1;
        memcpy(&r0, poly_block, 8);
        memcpy(&r1, poly_block + 8, 8);
        r0 &= 0x0ffffffc0fffffffULL;
        r1 &= 0x0ffffffc0ffffffcULL;

        size_t after[NT];
        size_t accb = 0;
        for (int i = NT - 1; i >= 0; i--) {
            after[i] = accb;
            accb += lens_c[i] / 16;
        }
        uint64_t H0 = 0, H1 = 0, H2 = 0;
        for (int i = 0; i < NT; i++) {
            uint32_t flag;
            memcpy(&flag, jobs[i].ctx + 0x14, 4);
            uint64_t h0, h1, h2, p0, p1, p2;
            from_ctx(jobs[i].ctx, flag != 0, &h0, &h1, &h2);
            if (after[i] == 0) { p0 = h0; p1 = h1; p2 = h2; }
            else {
                uint64_t e0, e1, e2;
                rpow(r0, r1, after[i], &e0, &e1, &e2);
                mul130(h0, h1, h2, e0, e1, e2, &p0, &p1, &p2);
            }
            add130(&H0, &H1, &H2, p0, p1, p2);
        }

        /* AAD: at most 32 bytes in this task, handle generally */
        if (aad_len) {
            unsigned char actx[256] __attribute__((aligned(64)));
            void *funcs[2];
            memset(actx, 0, 64);
            poly1305_init(actx, poly_block, funcs);
            poly_blocks(actx, aad_buf, aad_len, (blocks_fn)funcs[0]);
            uint32_t flag;
            memcpy(&flag, actx + 0x14, 4);
            uint64_t ah0, ah1, ah2, e0, e1, e2, p0, p1, p2;
            from_ctx(actx, flag != 0, &ah0, &ah1, &ah2);
            size_t ct_blocks = ((size_t)N / 16);
            size_t ct_rem = (size_t)N & 15;
            size_t scale = ct_blocks + (ct_rem ? 1 : 0);
            if (scale) {
                rpow(r0, r1, scale, &e0, &e1, &e2);
                mul130(ah0, ah1, ah2, e0, e1, e2, &p0, &p1, &p2);
            } else { p0 = ah0; p1 = ah1; p2 = ah2; }
            uint64_t T0 = p0, T1 = p1, T2 = p2;
            add130(&T0, &T1, &T2, H0, H1, H2);
            H0 = T0; H1 = T1; H2 = T2;
        }

        /* lengths block */
        uint64_t m0 = aad_len, m1 = (uint64_t)N;
        add130(&H0, &H1, &H2, m0, m1, 1);
        mul130(H0, H1, H2, r0, r1, 0, &H0, &H1, &H2);

        unsigned __int128 H = ((unsigned __int128)H1 << 64) | H0;
        if (H2 > 3 || (H2 == 3 && (H + 5 < H))) {
            unsigned __int128 s = H + 5;
            H0 = (uint64_t)s;
            H1 = (uint64_t)(s >> 64);
        }
        uint64_t s0, s1;
        memcpy(&s0, poly_block + 16, 8);
        memcpy(&s1, poly_block + 24, 8);
        unsigned __int128 sum = (unsigned __int128)H0 + s0;
        uint64_t f0 = (uint64_t)sum;
        uint64_t f1 = H1 + s1 + (uint64_t)(sum >> 64);
        memcpy(tag, &f0, 8);
        memcpy(tag + 8, &f1, 8);
    }

    OPENSSL_cleanse(poly_block, 64);
    PyBuffer_Release(&key); PyBuffer_Release(&nonce);
    PyBuffer_Release(&plaintext); PyBuffer_Release(&aad);
    return Py_BuildValue("(NN)", ct_obj, tag_obj);
}

static PyMethodDef methods[] = {
    {"encrypt", chacha_encrypt, METH_VARARGS, "encrypt"},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = { PyModuleDef_HEAD_INIT, "chacha_fast", NULL, -1, methods };
PyMODINIT_FUNC PyInit_chacha_fast(void) { return PyModule_Create(&moduledef); }
